const fs = require('fs');
const execSync = require('child_process').execSync;
const diff = execSync('git diff HEAD yarn.lock', { maxBuffer: 50 * 1024 * 1024 }).toString();
const lines = diff.split('\n');
const packageVersions = {};
let currentPackages = [];

// Parse yarn.lock diff to find actual package name and how version changed
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (line.match(/^@@/)) {
    currentPackages = [];
  }
  // If line defines packages (not starting with +/- but at top of entry)
  if (line.startsWith(' ') && line.endsWith(':') && !line.includes('resolved') && !line.includes('integrity') && !line.includes('dependencies:')) {
    currentPackages = line.trim().replace(/:$/, '').split(',').map(s => s.trim().replace(/['\"]/g, ''));
  }
  if (line.startsWith('-  version') || line.startsWith('+  version')) {
    const isAdded = line.startsWith('+');
    const version = line.split('\"')[1] || line.split(' ').pop().replace(/['\"]/g, '');
    for (const pkg of currentPackages) {
      if (!packageVersions[pkg]) packageVersions[pkg] = {};
      if (isAdded) packageVersions[pkg].new = version;
      else packageVersions[pkg].old = version;
    }
  }
}

// Keep only those that actually changed
const changed = {};
for (const [pkg, v] of Object.entries(packageVersions)) {
  if (v.old && v.new && v.old !== v.new) {
    changed[pkg] = v;
  }
}
console.log(JSON.stringify(changed, null, 2));
""}

