const fs = require('fs');
const execSync = require('child_process').execSync;

function parseLock(content) {
  const lines = content.split('\n');
  const packages = {};
  let currentKeys = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.match(/^#/) || line.trim() === '') {
      continue;
    }
    // If it's a line that doesn't start with space, it is a package definition
    if (!line.startsWith(' ')) {
      currentKeys = line.trim().replace(/:$/, '').split(',').map(s => s.trim().replace(/['\"]/g, ''));
    } else {
      const trimmed = line.trim();
      if (trimmed.startsWith('version ')) {
        const version = trimmed.split(' ')[1].replace(/['\"]/g, '');
        if (currentKeys) {
          for (const key of currentKeys) {
            packages[key] = version;
          }
        }
      }
    }
  }
  return packages;
}

const headLockContent = execSync('git show HEAD:yarn.lock', { maxBuffer: 50 * 1024 * 1024 }).toString();
const curLockContent = fs.readFileSync('yarn.lock', 'utf8');

const headPkgs = parseLock(headLockContent);
const curPkgs = parseLock(curLockContent);

const upgrades = [];
for (const [key, curVer] of Object.entries(curPkgs)) {
  const headVer = headPkgs[key];
  if (headVer && headVer !== curVer) {
    upgrades.push({ package: key, from: headVer, to: curVer });
  }
}

// Group by package name (without the version specifier) to see cleanly
const grouped = {};
for (const entry of upgrades) {
  const name = entry.package.split('@')[0] || entry.package;
  if (!grouped[name]) {
    grouped[name] = { from: new Set(), to: new Set() };
  }
  grouped[name].from.add(entry.from);
  grouped[name].to.add(entry.to);
}

const result = {};
for (const [name, sets] of Object.entries(grouped)) {
  result[name] = {
    from: Array.from(sets.from),
    to: Array.from(sets.to)
  };
}

console.log(JSON.stringify(result, null, 2));
""}

